begin;
do $$
declare
  v_site_id uuid;
  v_page_id uuid;
  v_document jsonb;
begin
  select id into v_site_id from website.sites where site_key='marktone-main' limit 1;
  select id into v_page_id from website.pages where site_id=v_site_id and is_home and status<>'archived' limit 1;
  if v_page_id is null then raise exception 'marktone_home_page_not_found'; end if;

  select content into v_document from website.pages where id=v_page_id for update;
  v_document:=jsonb_set(
    coalesce(v_document,'{}'::jsonb),
    '{blocks}',
    coalesce(v_document->'blocks','[]'::jsonb)||$blocks$[{"id":"row-platform","type":"columns","props":{"anchor":"platform","row":true,"layoutKey":"1","gap":18,"fullWidth":false,"minHeight":0,"verticalAlign":"stretch","items":[{"id":"col-platform","width":"1fr","modules":[{"id":"heading-platform","type":"heading","props":{"anchor":"","eyebrow":"Marktone Platform","title":"كل فريق يعمل بأدواته… وكل البيانات تلتقي في مكان واحد","body":"وحدات مترابطة تساعدك على الانتقال من إدارة يومية مشتتة إلى نظام تشغيل واضح وقابل للقياس.","level":"h2"},"style":{"variant":"light","align":"center","paddingY":10,"maxWidth":"reading","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-section-title"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}},{"id":"cards-platform","type":"cards","props":{"anchor":"","eyebrow":"","title":"","body":"","columns":4,"items":[{"title":"إدارة علاقات العملاء CRM","description":"ملف موحد للعميل والفرص والمتابعات ومصدر الاستحواذ.","href":"#contact"},{"title":"توزيع العملاء","description":"توزيع عادل أو مخصص مع مواعيد نهائية ومراقبة الاستجابة.","href":"#contact"},{"title":"تقويم المهام","description":"مهام ومواعيد وتذكيرات مرتبطة بالعميل والفريق.","href":"#contact"},{"title":"التسجيل والقبول","description":"تسليم منظم من المبيعات إلى التسجيل واستكمال المتطلبات.","href":"#contact"},{"title":"إدارة البرامج والدورات","description":"كتالوج ودورات وتشغيل ومزامنة مع المتاجر المتصلة.","href":"#contact"},{"title":"الأتمتة والرسائل","description":"قواعد تشغيل ورسائل ذكية تقلل العمل اليدوي المتكرر.","href":"#contact"},{"title":"التقارير والتحليلات","description":"لوحات أداء للمبيعات والمهام والحملات والتشغيل.","href":"#contact"},{"title":"الموقع والبيلدر","description":"CMS احترافي وصفحات هبوط ومقالات وقوائم قابلة للتعديل.","href":"#contact"}]},"style":{"variant":"light","align":"right","paddingY":10,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-platform-grid"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}],"style":{"background":"","color":"","padding":0,"gap":14,"borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","verticalAlign":"stretch"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}]},"style":{"variant":"light","align":"center","paddingY":90,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-platform-section"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}},{"id":"row-how","type":"columns","props":{"anchor":"how","row":true,"layoutKey":"1","gap":18,"fullWidth":false,"minHeight":0,"verticalAlign":"stretch","items":[{"id":"col-how","width":"1fr","modules":[{"id":"heading-how","type":"heading","props":{"anchor":"","eyebrow":"كيف تبدأ؟","title":"من التفعيل إلى النمو في ثلاث خطوات واضحة","body":"نجهز بيئة العمل، نربط مصادر البيانات، ثم نطلق التشغيل والقياس دون تعقيد.","level":"h2"},"style":{"variant":"light","align":"center","paddingY":10,"maxWidth":"reading","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-section-title"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}},{"id":"timeline-how","type":"timeline","props":{"anchor":"","eyebrow":"","title":"","items":[{"value":"01","title":"جهّز مركزك","description":"أضف بيانات المنشأة، فريق العمل، الصلاحيات، البرامج والقنوات المتصلة."},{"value":"02","title":"ابدأ جذب وتسجيل العملاء","description":"استقبل العملاء من الحملات والموقع والمتجر ووزعهم على الفريق مع مسار متابعة واضح."},{"value":"03","title":"شغّل، قِس وطوّر","description":"تابع التسجيل والتشغيل ومؤشرات الأداء واتخذ قرارات النمو من لوحة واحدة."}]},"style":{"variant":"light","align":"right","paddingY":20,"maxWidth":"reading","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-how"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}],"style":{"background":"","color":"","padding":0,"gap":14,"borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","verticalAlign":"stretch"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}]},"style":{"variant":"paper","align":"center","paddingY":85,"maxWidth":"wide","background":"","color":"","borderColor":"","borderWidth":0,"borderRadius":0,"shadow":"none","animation":"none","animationDelay":0,"cssClass":"mt-how-row"},"responsive":{"hideDesktop":false,"hideTablet":false,"hideMobile":false}}]$blocks$::jsonb,
    true
  );
  v_document:=private_app.website_builder_validate_document(v_document);

  update website.pages set content=v_document,updated_at=now() where id=v_page_id;
  update website.content_documents
  set draft_document=v_document,published_document=v_document,
      draft_updated_at=now(),published_at=now(),updated_at=now()
  where site_id=v_site_id and entity_type='page' and entity_id=v_page_id;
end
$$;
commit;
